import{_ as e,c as l,o as i,b2 as o}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"参数设置设计文档（方案A）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-13-parameter-settings-design.md","filePath":"superpowers/specs/2026-05-13-parameter-settings-design.md"}'),r={name:"superpowers/specs/2026-05-13-parameter-settings-design.md"};function t(n,a,d,c,h,s){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="参数设置设计文档-方案a" tabindex="-1">参数设置设计文档（方案A） <a class="header-anchor vp-link" href="#参数设置设计文档-方案a" aria-label="Permalink to &quot;参数设置设计文档（方案A）&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>参数设置模块用于维护系统运行参数，覆盖查询、分页、新增、编辑、删除、导出、缓存刷新，并复用系统操作日志满足审计需求。</p><p>本次按最小改造路径实施，目标是在不扩张模型复杂度的前提下完成稳定交付。</p><h2 id="_2-范围与非范围" tabindex="-1">2. 范围与非范围 <a class="header-anchor vp-link" href="#_2-范围与非范围" aria-label="Permalink to &quot;2. 范围与非范围&quot;">​</a></h2><h3 id="_2-1-实施范围" tabindex="-1">2.1 实施范围 <a class="header-anchor vp-link" href="#_2-1-实施范围" aria-label="Permalink to &quot;2.1 实施范围&quot;">​</a></h3><ul><li>参数查询与分页。</li><li>参数新增、编辑、删除。</li><li>全量刷新参数缓存。</li><li>按当前筛选条件导出参数（全量结果）。</li><li>参数变更纳入系统操作日志。</li></ul><h3 id="_2-2-明确不做" tabindex="-1">2.2 明确不做 <a class="header-anchor vp-link" href="#_2-2-明确不做" aria-label="Permalink to &quot;2.2 明确不做&quot;">​</a></h3><ul><li>不做敏感值判定。</li><li>不做脱敏展示。</li><li>不做明文查看/编辑权限拆分。</li><li>不新增“值类型”字段，<code>configValue</code> 统一按字符串处理。</li></ul><h2 id="_3-业务规则" tabindex="-1">3. 业务规则 <a class="header-anchor vp-link" href="#_3-业务规则" aria-label="Permalink to &quot;3. 业务规则&quot;">​</a></h2><h3 id="_3-1-唯一性" tabindex="-1">3.1 唯一性 <a class="header-anchor vp-link" href="#_3-1-唯一性" aria-label="Permalink to &quot;3.1 唯一性&quot;">​</a></h3><ul><li><code>configKey</code> 全局唯一。</li><li>唯一性由后端强制校验，前端仅可做基础提示。</li><li>冲突时返回中文业务提示。</li></ul><h3 id="_3-2-系统内置参数规则" tabindex="-1">3.2 系统内置参数规则 <a class="header-anchor vp-link" href="#_3-2-系统内置参数规则" aria-label="Permalink to &quot;3.2 系统内置参数规则&quot;">​</a></h3><ul><li>系统内置参数可查询、可导出。</li><li>系统内置参数不可删除。</li><li>系统内置参数仅允许编辑 <code>configValue</code>，禁止修改 <code>configKey</code>、<code>configName</code>、内置标记等关键属性。</li></ul><h3 id="_3-3-失败提示规则" tabindex="-1">3.3 失败提示规则 <a class="header-anchor vp-link" href="#_3-3-失败提示规则" aria-label="Permalink to &quot;3.3 失败提示规则&quot;">​</a></h3><ul><li>所有业务失败提示统一中文文案。</li><li>业务失败通过项目自定义异常表达，不使用 <code>IllegalArgumentException</code>。</li></ul><h2 id="_4-后端设计" tabindex="-1">4. 后端设计 <a class="header-anchor vp-link" href="#_4-后端设计" aria-label="Permalink to &quot;4. 后端设计&quot;">​</a></h2><h3 id="_4-1-分层与职责" tabindex="-1">4.1 分层与职责 <a class="header-anchor vp-link" href="#_4-1-分层与职责" aria-label="Permalink to &quot;4.1 分层与职责&quot;">​</a></h3><ul><li>Controller：参数接口编排、参数接收与返回。</li><li>Service：规则校验（唯一性、内置限制）、业务流程、缓存刷新协调。</li><li>Mapper：参数数据访问。</li><li>DTO/VO：入参校验模型与出参模型。</li></ul><h3 id="_4-2-接口设计-按约束统一-post-语义" tabindex="-1">4.2 接口设计（按约束统一 POST 语义） <a class="header-anchor vp-link" href="#_4-2-接口设计-按约束统一-post-语义" aria-label="Permalink to &quot;4.2 接口设计（按约束统一 POST 语义）&quot;">​</a></h3><ul><li><code>GET /system/config/list</code>：分页查询。</li><li><code>GET /system/config/{configId}</code>：详情查询。</li><li><code>GET /system/config/configKey/{configKey}</code>：按键名查询。</li><li><code>POST /system/config/create</code>：新增参数。</li><li><code>POST /system/config/update</code>：编辑参数。</li><li><code>POST /system/config/remove</code>：删除参数（支持批量 ID）。</li><li><code>POST /system/config/refreshCache</code>：全量刷新缓存。</li><li><code>POST /system/config/export</code>：导出参数。</li></ul><p>说明：原需求中的 <code>PUT/DELETE</code> 语义按仓库约束调整为 <code>POST</code>，避免接口风格分裂。</p><h3 id="_4-3-校验与文档注解" tabindex="-1">4.3 校验与文档注解 <a class="header-anchor vp-link" href="#_4-3-校验与文档注解" aria-label="Permalink to &quot;4.3 校验与文档注解&quot;">​</a></h3><ul><li>所有写接口接入 Jakarta Validation。</li><li>对外接口补齐 <code>@Tag</code>、<code>@Operation</code>、关键参数 <code>@Parameter</code>。</li><li>对关键业务失败场景输出明确中文错误信息。</li></ul><h3 id="_4-4-审计与日志" tabindex="-1">4.4 审计与日志 <a class="header-anchor vp-link" href="#_4-4-审计与日志" aria-label="Permalink to &quot;4.4 审计与日志&quot;">​</a></h3><ul><li>不新增参数历史表。</li><li>参数新增/编辑/删除/刷新缓存操作复用系统操作日志能力。</li></ul><h2 id="_5-前端设计" tabindex="-1">5. 前端设计 <a class="header-anchor vp-link" href="#_5-前端设计" aria-label="Permalink to &quot;5. 前端设计&quot;">​</a></h2><h3 id="_5-1-页面结构" tabindex="-1">5.1 页面结构 <a class="header-anchor vp-link" href="#_5-1-页面结构" aria-label="Permalink to &quot;5.1 页面结构&quot;">​</a></h3><ul><li>查询区：参数名称、参数键名、系统内置、创建时间区间。</li><li>操作区：新增、导出、刷新缓存。</li><li>表格区：参数主键、参数名称、参数键名、参数键值、系统内置、备注、创建时间、操作列。</li><li>分页区：页码、页大小、总数。</li></ul><p>页面风格与交互对齐 <code>system/dict/type</code>。</p><h3 id="_5-2-交互细节" tabindex="-1">5.2 交互细节 <a class="header-anchor vp-link" href="#_5-2-交互细节" aria-label="Permalink to &quot;5.2 交互细节&quot;">​</a></h3><ul><li>支持回车触发查询。</li><li>支持一键重置查询条件。</li><li>新增/编辑使用弹窗表单，必填校验：参数名称、参数键名、参数键值。</li><li>删除操作二次确认；内置参数删除需禁用按钮或明确提示不可删除。</li><li>刷新缓存为同步交互：点击后等待结果，成功提示后刷新列表。</li><li>导出按当前筛选条件导出全量结果。</li></ul><h3 id="_5-3-权限控制" tabindex="-1">5.3 权限控制 <a class="header-anchor vp-link" href="#_5-3-权限控制" aria-label="Permalink to &quot;5.3 权限控制&quot;">​</a></h3><p>沿用既有权限点：</p><ul><li><code>system:config:list</code></li><li><code>system:config:add</code></li><li><code>system:config:edit</code></li><li><code>system:config:remove</code></li><li><code>system:config:export</code></li><li><code>system:config:query</code></li></ul><h2 id="_6-数据流与状态一致性" tabindex="-1">6. 数据流与状态一致性 <a class="header-anchor vp-link" href="#_6-数据流与状态一致性" aria-label="Permalink to &quot;6. 数据流与状态一致性&quot;">​</a></h2><h3 id="_6-1-新增-编辑" tabindex="-1">6.1 新增/编辑 <a class="header-anchor vp-link" href="#_6-1-新增-编辑" aria-label="Permalink to &quot;6.1 新增/编辑&quot;">​</a></h3><p>提交成功后关闭弹窗，提示成功，并按当前筛选条件刷新列表。</p><h3 id="_6-2-删除" tabindex="-1">6.2 删除 <a class="header-anchor vp-link" href="#_6-2-删除" aria-label="Permalink to &quot;6.2 删除&quot;">​</a></h3><p>删除成功后刷新列表；若当前页数据清空，自动回退到上一有效页。</p><h3 id="_6-3-刷新缓存" tabindex="-1">6.3 刷新缓存 <a class="header-anchor vp-link" href="#_6-3-刷新缓存" aria-label="Permalink to &quot;6.3 刷新缓存&quot;">​</a></h3><p>刷新成功后提示并刷新列表。参数读取即时生效由后端缓存策略保障。</p><h2 id="_7-错误处理策略" tabindex="-1">7. 错误处理策略 <a class="header-anchor vp-link" href="#_7-错误处理策略" aria-label="Permalink to &quot;7. 错误处理策略&quot;">​</a></h2><ul><li>统一返回可读中文错误。</li><li>典型错误场景： <ul><li><code>configKey</code> 重复。</li><li>删除内置参数被禁止。</li><li>编辑内置参数时修改了非 <code>configValue</code> 字段。</li><li>刷新缓存失败。</li></ul></li></ul><h2 id="_8-测试与验收映射" tabindex="-1">8. 测试与验收映射 <a class="header-anchor vp-link" href="#_8-测试与验收映射" aria-label="Permalink to &quot;8. 测试与验收映射&quot;">​</a></h2><h3 id="_8-1-后端验证点" tabindex="-1">8.1 后端验证点 <a class="header-anchor vp-link" href="#_8-1-后端验证点" aria-label="Permalink to &quot;8.1 后端验证点&quot;">​</a></h3><ul><li><code>configKey</code> 全局唯一校验生效。</li><li>内置参数删除拦截生效。</li><li>内置参数仅可编辑 <code>configValue</code>。</li><li>刷新缓存成功/失败路径可验证。</li></ul><h3 id="_8-2-前端验证点" tabindex="-1">8.2 前端验证点 <a class="header-anchor vp-link" href="#_8-2-前端验证点" aria-label="Permalink to &quot;8.2 前端验证点&quot;">​</a></h3><ul><li>查询、重置、分页联动正常。</li><li>新增/编辑后列表及时刷新且数据可见。</li><li>删除确认交互正确，内置参数删除提示清晰。</li><li>导出结果与筛选条件一致。</li></ul><h3 id="_8-3-验收标准对齐" tabindex="-1">8.3 验收标准对齐 <a class="header-anchor vp-link" href="#_8-3-验收标准对齐" aria-label="Permalink to &quot;8.3 验收标准对齐&quot;">​</a></h3><p>对齐需求文档验收项，并按已确认范围去除“敏感值脱敏与明文权限”相关要求。</p><h2 id="_9-实施边界与后续扩展" tabindex="-1">9. 实施边界与后续扩展 <a class="header-anchor vp-link" href="#_9-实施边界与后续扩展" aria-label="Permalink to &quot;9. 实施边界与后续扩展&quot;">​</a></h2><p>当前方案优先保证快速落地与稳定交付。若后续需要敏感值管理能力，建议单独立项新增：</p><ul><li>敏感参数识别策略。</li><li>脱敏展示规则。</li><li>明文查看/编辑权限模型。</li><li>审计增强与风险控制。</li></ul>',54)])])}const _=e(r,[["render",t]]);export{p as __pageData,_ as default};
